.sl-cta-glass-wrap {
    padding-block: clamp(3rem, 6vw, 5.5rem);
    background-color: var(--smartlearn-bg);
    background: linear-gradient(135deg, color-mix(in srgb, var(--smartlearn-primary) 22%, var(--smartlearn-bg)), color-mix(in srgb, var(--smartlearn-primary) 10%, var(--smartlearn-card-bg)));
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-glass-wrap .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-cta-glass-wrap .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-cta-glass-wrap .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-cta-glass-wrap .sl-glass-card {
    padding: clamp(2rem, 5vw, 4rem);
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 82%, transparent);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
}
[data-bs-theme="dark"] .sl-cta-glass-wrap .sl-glass-card,
[data-smartlearn-mode="dark"] .sl-cta-glass-wrap .sl-glass-card {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 88%, transparent);
    border-color: var(--smartlearn-card-border) !important;
}
.sl-cta-glass-wrap .sl-btn-glass-cta {
    background-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    border: 2px solid transparent !important;
    transition: transform 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease;
}
.sl-cta-glass-wrap .sl-btn-glass-cta:hover,
.sl-cta-glass-wrap .sl-btn-glass-cta:focus-visible {
    transform: translateY(-2px);
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
}
.sl-cta-glass-wrap .sl-btn-glass-cta:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-glass-wrap .sl-btn-glass-cta { transition: none; }
    .sl-cta-glass-wrap .sl-btn-glass-cta:hover,
    .sl-cta-glass-wrap .sl-btn-glass-cta:focus-visible { transform: none; }
}
